# Python 2 legacy tests
import unittest

from billing import build_invoice


class BillingTests(unittest.TestCase):

    def setUp(self):
        self.items = [
            {"name": "Laptop", "price": 2000, "quantity": 1},
            {"name": "Mouse", "price": 500, "quantity": 2}
        ]

    def test_invoice_total(self):
        invoice = build_invoice("Alice", self.items)

        self.assertEqual(invoice.subtotal(), 3000)
        self.assertEqual(invoice.discount(), 300)
        self.assertEqual(invoice.tax(), 486)
        self.assertEqual(invoice.total(), 3186)

    def test_customer_name_is_normalized(self):
        invoice = build_invoice("  Alice  ", self.items)
        self.assertEqual(invoice.customer_name, "alice")

    def test_empty_invoice_is_rejected(self):
        self.assertRaises(ValueError, build_invoice, "Alice", [])

    def test_item_count(self):
        invoice = build_invoice("Alice", self.items)
        self.assertEqual(invoice.item_count(), 3)


if __name__ == "__main__":
    unittest.main()

